concord::api! {
    pub client Tasks {
        base "https://tasks.example.com/api/tasks";
        read Json;                                  // this API answers in JSON

        GET list(done?: bool) -> Vec<Task> {
            query { done; }
        }

        POST create(task: NewTask) -> Task {
            body json(task);
        }

        GET get(id: u64) -> Task { path "{id}"; }

        DELETE delete(id: u64) { path "{id}"; }
    }
}

pub client Riot(key: Secret) {
    headers { "x-riot-token" = key; }                  // who you are, on every request below
    read Json;                                         // how this API answers
    problem RiotProblem;                               // how this API says no

    scope matches(route: MatchRoute) {
        base "https://{route}.api.riotgames.com";      // every request below
        path "lol/match/v5/matches";

        GET ids(puuid: Puuid, count?: u32) -> Vec<MatchId> {
            path "by-puuid/{puuid}/ids";
            query { count; }
        }

        GET get(id: MatchId) -> Match { path "{id}"; }
    }
}

/// `None` when there is no such player.
GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
    path "by-riot-id/{game_name}/{tag_line}";
    status { 404 => None }
}

GET ids(puuid: Puuid, start?: u32, count?: u32) -> Vec<MatchId> {
    path "by-puuid/{puuid}/ids";
    query { start; count; }
    paginate by_offset_limit(start, count);
}

pub client Stripe(key: Secret) {
    base "https://api.stripe.com";
    headers { "authorization" = "Bearer {key}"; }
    read Json;

    part page(limit?: u32, starting_after?: String) {
        query { limit; starting_after; }
        paginate by_cursor(starting_after, List::next_cursor);
    }

    scope customers {
        path "v1/customers";
        GET list(email?: String, ..page) -> List<Customer> { query { email; } }
    }

    scope invoices {
        path "v1/invoices";
        GET list(..page) -> List<Invoice>;
    }
}

/// Is it there?
HEAD exists(id: DocId) -> bool {
    path "{id}";
    status { 2xx => true, 404 => false }
}

/// The new document, and where it lives.
POST create(doc: NewDoc) -> Created {
    body json(doc);
    status {
        2xx { body, headers } => Created { doc: body, at: headers.require("location")?.to_owned() },
    }
}

/// Plain text, not JSON.
GET readme(repo: String) -> String {
    path "{repo}/readme";
    read Text;
}

/// A diff: a header of its own, and the bytes as they come.
GET diff() -> Bytes {
    headers { "accept" = "application/vnd.github.diff"; }
    read Binary;
}

/// A large file, as it comes.
GET download(id: FileId) -> concord::ByteStream {
    path "files/{id}";
    read Stream;                       // `use concord::read::Stream;`
}

/// An upload, on another host.
PUT upload(name: String, file: concord::Body) {
    base "https://uploads.example.com";
    headers { override "authorization" = "Bearer {client.key}"; }    // the key goes to this host too
    path "files/{name}";
    body file;
}

/// A body made of several inputs. A `cursor` that was not set is left out.
POST search(text: String, cursor?: String) -> Page {
    path "search";
    body json { text; cursor; }
}

pub client Vault(key: Secret) {
    middleware Signed::new(key.clone());      // every request is signed as it leaves
    // base, read, endpoints …
}

concord::api! {
    /// The Riot Games API (League of Legends subset).
    pub client Riot(
        /// The API key. Sent on every request unless an endpoint removes it.
        key: Secret,
    ) {
        headers { "x-riot-token" = key; }
        read Json;
        problem RiotProblem;

        /// Accounts (regional routing).
        scope account(route: AccountRoute) {
            base "https://{route}.api.riotgames.com";
            path "riot/account/v1/accounts";

            /// The account behind a Riot ID (`name#tag`). `None` when there is no such player.
            GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
                path "by-riot-id/{game_name}/{tag_line}";
                status { 404 => None }
            }

            /// The account of a signed-in player.
            /// Uses the player's own token instead of the API key.
            GET me(access_token: Secret) -> Account {
                path "me";
                headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
            }
        }

        /// Matches (regional routing).
        scope matches(route: MatchRoute) {
            base "https://{route}.api.riotgames.com";
            path "lol/match/v5/matches";

            /// Match ids of a player, newest first.
            GET ids(
                puuid: Puuid,
                start?: u32,
                count?: u32,
                queue?: i32,
                start_time?: i64,
            ) -> Vec<MatchId> {
                path "by-puuid/{puuid}/ids";
                query { start; count; queue; "startTime" = start_time; }
                paginate by_offset_limit(start, count);
            }

            /// One match.
            GET get(id: MatchId) -> Match { path "{id}"; }
        }
    }
}

/// GitHub's uploads live on another host.
POST upload_asset(name: String, file: concord::Body) -> Asset {
    base "https://uploads.github.com";
    headers { override "authorization" = "Bearer {client.token}"; }     // or: remove "authorization";
    path "assets";
    query { name; }
    body file;
}

part formatted(parse_mode?: ParseMode, disable_notification?: bool) {
    body json { parse_mode; disable_notification; }
}

POST send_message(chat_id: ChatId, text: String, ..formatted) -> Message {
    path "sendMessage";
    body json { chat_id; text; "reply_markup" = markup_of(text); }
}

POST token(grant_type: String, client_id: String, client_secret: Secret) -> Token {
    path "oauth/token";
    body form { grant_type; client_id; client_secret; }
}

GET get_updates(offset?: i64, timeout?: u32) -> Vec<Update> {
    path "getUpdates";
    query { offset; timeout; }
    idle_timeout Duration::from_secs(u64::from(timeout.unwrap_or(0)) + 10);
}

pub client Stripe(key: Secret) {
    base "https://api.stripe.com";
    headers { "authorization" = "Bearer {key}"; }
    read Json;
    problem StripeProblem;

    part page(limit?: u32, starting_after?: String) {
        query { limit; starting_after; }
        paginate by_cursor(starting_after, List::next_cursor);
    }
    part keyed(idempotency_key: String) {
        headers { "idempotency-key" = idempotency_key; }
        idempotent;
    }

    scope customers {
        path "v1/customers";
        GET list(email?: String, ..page) -> List<Customer> { query { email; } }
        POST create(customer: NewCustomer, ..keyed) -> Customer { body form(customer); }
    }
}

pub client Vault(key: Secret) {
    base "https://api.vault.example";
    read Json;
    middleware Signed::new(key.clone());        // every request is signed as it leaves

    GET balance() -> Balance { path "balance"; }
}

GET readme(owner: String, repo: String) -> String {
    path "repos/{owner}/{repo}/readme";
    headers { override "accept" = "application/vnd.github.raw+json"; }
    read Text;
}

POST create(request: ChatRequest) -> ChatReply {
    body json(request);
    read ChatRead(request.stream);          // your reader: `Json` or `Stream`, by this flag
}

GET pdf(id: InvoiceId) -> concord::ByteStream {
    path "invoices/{id}/pdf";
    read Stream;
}

/// `None` when there is no such player.
GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
    path "by-riot-id/{game_name}/{tag_line}";
    status { 404 => None }
}

/// A document with its version, for the `If-Match` of the next call.
GET get(id: DocId) -> Versioned<Doc> {
    path "{id}";
    status { 2xx { body, headers } => Versioned { etag: headers.get("etag").map(String::from), value: body } }
}

/// Is it there?
HEAD exists(id: DocId) -> bool {
    path "{id}";
    status { 2xx => true, 404 => false }
}

POST create(task: NewTask) -> Created {
    body json(task);
    status { 2xx { body, headers } => created(body, headers)? }
}

POST charge(new: NewCharge) -> Result<Charge, Declined> {
    path "charges";
    body form(new);
    status { 402 { body } => Err(body) }
}

part formatted(parse_mode?: ParseMode, disable_notification?: bool) {
    body json { parse_mode; disable_notification; }
}

POST send_message(chat_id: ChatId, text: String, ..formatted) -> Message {
    path "sendMessage";
    body json { chat_id; text; "reply_markup" = markup_of(text); }
}

POST send_photo(chat_id: ChatId, photo: concord::Body) -> Message {
    path "sendPhoto";
    body multipart()
        .text("chat_id", chat_id)
        .file("photo", "photo.jpg", "image/jpeg", photo)
        .finish();
}

pub client Vault(key: Secret) {
    base "https://api.vault.example";
    read Json;
    middleware Signed::new(key.clone());        // every request is signed as it leaves

    GET balance() -> Balance { path "balance"; }
}

POST create(new: NewCustomer, idempotency_key: String) -> Customer {
    body form(new);
    headers { "idempotency-key" = idempotency_key; }
    idempotent;                    // this API promises: the same key, the same result
}

POST charge(new: NewCharge, key?: String) -> Charge {
    body form(new);
    headers { "idempotency-key" = key; }
    idempotent key.is_some();      // safe to repeat only when the caller gave a key
}

GET list(limit?: u32, starting_after?: String) -> List<Customer> {
    query { limit; starting_after; }
    paginate move |call, page| page.value().next_cursor().map(|cursor| call.starting_after(cursor));
}

part page(limit?: u32, starting_after?: String) {
        query { limit; starting_after; }
        paginate by_cursor(starting_after, List::next_cursor);
    }

scope customers {
        path "v1/customers";
        GET list(email?: String, ..page) -> List<Customer> { query { email; } }
    }

GET get_updates(offset?: i64, timeout?: u32) -> Vec<Update> {
    path "getUpdates";
    query { offset; timeout; }
    idle_timeout Duration::from_secs(u64::from(timeout.unwrap_or(0)) + 10);
}

concord::api! {
    /// League of Legends, Teamfight Tactics and Riot accounts.
    ///
    /// A route is a host. A platform (`euw1`, `kr`) holds what lives on one server; a region
    /// (`europe`, `asia`) holds accounts and matches. `Platform::region()` gives the one of the other.
    /// Retry is off: `.with_retry(Retry::standard())` waits out a `429` on every `GET`.
    pub client Riot(
        /// The key of the developer portal. A development key lasts a day.
        key: Secret,
    ) {
        headers { "x-riot-token" = key; }
        read Json;
        problem RiotProblem;
        /// Riot's limits, per host and per method, shared by every call of this client.
        /// It waits before a request that the last answers say is over a limit, and
        /// holds the host or the method for `Retry-After` after a `429`.
        middleware Quota::new();

        /// The signed-in player: the token of Riot Sign On, in place of the API key.
        part player(access_token: Secret) {
            headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
        }
        /// A match history, newest first: `.start(…)`, `.count(…)` (1 to 100; Riot gives 20),
        /// `.start_time(…)`, `.end_time(…)` in Unix seconds. It ends on a page shorter than `count`.
        part history(start?: u32, count?: u32, start_time?: i64, end_time?: i64) {
            query { start; count; "startTime" = start_time; "endTime" = end_time; }
            paginate by_offset_limit(start, count);
        }
        /// The filters of a LoL history: `.queue(420)` (ranked solo), `.kind(MatchType::Ranked)`.
        part lol_filter(queue?: i32, kind?: MatchType) {
            query { queue; "type" = kind; }
        }
        /// A ladder by page number, from 1: `.page(…)`. It ends on an empty page.
        part ladder(page?: u32) {
            query { page; }
            paginate by_page(page, 1);
        }
        /// A ranked queue of TFT: `.queue(…)`. Riot reads `RANKED_TFT` when it is not set.
        part tft_queue(queue?: TftQueue) {
            query { queue; }
        }

        // ---- groups of one endpoint: the route is the endpoint's own input

        /// champion-v3: the free champions of the week, and those for new players.
        GET champion_rotations(route: Platform) -> ChampionRotations {
            base "https://{route}.api.riotgames.com";
            path "lol/platform/v3/champion-rotations";
        }
        /// lol-status-v4: the maintenances and incidents of a platform.
        GET lol_status(route: Platform) -> PlatformData {
            base "https://{route}.api.riotgames.com";
            path "lol/status/v4/platform-data";
        }
        /// tft-status-v1.
        GET tft_status(route: Platform) -> PlatformData {
            base "https://{route}.api.riotgames.com";
            path "tft/status/v1/platform-data";
        }
        /// third-party-code-v4: the code a player typed in the client, to prove an account is theirs.
        #[deprecated(note = "keyed by summoner id (unsure: still served)")]
        GET third_party_code(route: Platform, summoner_id: SummonerId) -> Option<String> {
            base "https://{route}.api.riotgames.com";
            path "lol/platform/v4/third-party-code/by-summoner/{summoner_id}";
            status { 404 => None }
        }

        // ---- regional hosts: americas, asia, europe, sea

        /// account-v1. An account can be found from any region; the nearest is the quickest.
        /// (unsure: whether `sea` serves it)
        scope account(route: Region) {
            base "https://{route}.api.riotgames.com";
            path "riot/account/v1";

            /// `None` when there is no such account.
            GET by_puuid(puuid: Puuid) -> Option<Account> {
                path "accounts/by-puuid/{puuid}";
                status { 404 => None }
            }
            /// The account behind a Riot ID, `game_name#tag_line`. `None` when there is none.
            GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
                path "accounts/by-riot-id/{game_name}/{tag_line}";
                status { 404 => None }
            }
            /// The signed-in player.
            GET me(..player) -> Account { path "accounts/me"; }
            /// The shard of a player, for a game that has shards (`val`, `lor`).
            GET active_shard(game: Game, puuid: Puuid) -> Option<ActiveShard> {
                path "active-shards/by-game/{game}/by-puuid/{puuid}";
                status { 404 => None }
            }
            /// The platform a player of `lol` or `tft` plays on. (unsure: path and answer)
            GET active_region(game: Game, puuid: Puuid) -> Option<ActiveRegion> {
                path "region/by-game/{game}/by-puuid/{puuid}";
                status { 404 => None }
            }
        }

        /// match-v5. A match lives in the region of its platform: `EUW1_…` in `europe`.
        scope matches(route: Region) {
            base "https://{route}.api.riotgames.com";
            path "lol/match/v5/matches";

            /// The ids of a player's matches, newest first.
            GET ids(puuid: Puuid, ..history, ..lol_filter) -> Vec<MatchId> {
                path "by-puuid/{puuid}/ids";
            }
            /// `None` when there is no such match here: past Riot's retention, or in another region.
            GET get(id: MatchId) -> Option<Match> {
                path "{id}";
                status { 404 => None }
            }
            /// The match minute by minute: frames and events.
            GET timeline(id: MatchId) -> Option<Timeline> {
                path "{id}/timeline";
                status { 404 => None }
            }
            /// The replays of a player's recent matches. (unsure: the whole endpoint)
            GET replays(puuid: Puuid) -> Replays { path "by-puuid/{puuid}/replays"; }
        }

        /// tft-match-v1. Its ids are not LoL's.
        scope tft_matches(route: Region) {
            base "https://{route}.api.riotgames.com";
            path "tft/match/v1/matches";

            GET ids(puuid: Puuid, ..history) -> Vec<TftMatchId> { path "by-puuid/{puuid}/ids"; }
            GET get(id: TftMatchId) -> Option<TftMatch> {
                path "{id}";
                status { 404 => None }
            }
        }

        /// lol-rso-match-v1: the matches of the signed-in player, custom games too.
        /// (unsure: the paths, and which filters it takes)
        scope rso_matches(route: Region, ..player) {
            base "https://{route}.api.riotgames.com";
            path "lol/rso-match/v1/matches";

            GET ids(..history, ..lol_filter) -> Vec<MatchId> { path "ids"; }
            GET get(id: MatchId) -> Option<Match> {
                path "{id}";
                status { 404 => None }
            }
            GET timeline(id: MatchId) -> Option<Timeline> {
                path "{id}/timeline";
                status { 404 => None }
            }
        }

        /// tournament-v5, or its stub: the same calls with no real game behind them, to build
        /// and test against. Needs a key that Riot enabled for tournaments.
        /// (unsure: served on `americas` only)
        scope tournament(api: TournamentApi) {
            base "https://americas.api.riotgames.com";
            path "lol/{api}/v5";

            /// Where Riot posts the result of each game: once for a region and a callback URL.
            POST register_provider(provider: NewProvider) -> ProviderId {
                path "providers";
                body json(provider);
            }
            POST create(registration: NewTournament) -> TournamentId {
                path "tournaments";
                body json(registration);
            }
            /// `count` codes, 1 to 1000. (unsure: Riot makes one when it is not set)
            POST create_codes(tournament_id: TournamentId, settings: CodeSettings, count?: u32)
                -> Vec<TournamentCode>
            {
                path "codes";
                query { "tournamentId" = tournament_id; count; }
                body json(settings);
            }
            GET code(code: TournamentCode) -> Option<CodeDetails> {
                path "codes/{code}";
                status { 404 => None }
            }
            GET lobby_events(code: TournamentCode) -> LobbyEvents { path "lobby-events/by-code/{code}"; }
            /// Not on the stub.
            PUT update_code(code: TournamentCode, update: CodeUpdate) {
                path "codes/{code}";
                body json(update);
            }
            /// The games played with a code. Not on the stub.
            GET games(code: TournamentCode) -> Vec<TournamentGame> { path "games/by-code/{code}"; }
        }

        // ---- platform hosts: br1, eun1, euw1, jp1, kr, la1, la2, me1, na1, oc1, ru, sg2, tr1, tw2, vn2

        /// champion-mastery-v4.
        scope champion_mastery(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/champion-mastery/v4";

            /// Every champion the player has played.
            GET by_puuid(puuid: Puuid) -> Vec<ChampionMastery> {
                path "champion-masteries/by-puuid/{puuid}";
            }
            /// `None` when the player has never played this champion.
            GET by_champion(puuid: Puuid, champion: ChampionId) -> Option<ChampionMastery> {
                path "champion-masteries/by-puuid/{puuid}/by-champion/{champion}";
                status { 404 => None }
            }
            /// The best champions. Riot gives 3 when `count` is not set.
            GET top(puuid: Puuid, count?: u32) -> Vec<ChampionMastery> {
                path "champion-masteries/by-puuid/{puuid}/top";
                query { count; }
            }
            /// The sum of the mastery levels of every champion.
            GET score(puuid: Puuid) -> i32 { path "scores/by-puuid/{puuid}"; }

            // Keyed by summoner id, which Riot retired for the PUUID. (unsure: still served)
            #[deprecated(note = "use by_puuid")]
            GET by_summoner(summoner_id: SummonerId) -> Vec<ChampionMastery> {
                path "champion-masteries/by-summoner/{summoner_id}";
            }
            #[deprecated(note = "use by_champion")]
            GET by_summoner_champion(summoner_id: SummonerId, champion: ChampionId)
                -> Option<ChampionMastery>
            {
                path "champion-masteries/by-summoner/{summoner_id}/by-champion/{champion}";
                status { 404 => None }
            }
            #[deprecated(note = "use top")]
            GET top_by_summoner(summoner_id: SummonerId, count?: u32) -> Vec<ChampionMastery> {
                path "champion-masteries/by-summoner/{summoner_id}/top";
                query { count; }
            }
            #[deprecated(note = "use score")]
            GET score_by_summoner(summoner_id: SummonerId) -> i32 {
                path "scores/by-summoner/{summoner_id}";
            }
        }

        /// clash-v1.
        scope clash(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/clash/v1";

            /// The player's places in Clash teams; empty when there is none.
            GET players(puuid: Puuid) -> Vec<ClashPlayer> { path "players/by-puuid/{puuid}"; }
            #[deprecated(note = "use players")]
            GET players_by_summoner(summoner_id: SummonerId) -> Vec<ClashPlayer> {
                path "players/by-summoner/{summoner_id}";
            }
            GET team(id: ClashTeamId) -> Option<ClashTeam> {
                path "teams/{id}";
                status { 404 => None }
            }
            /// The tournaments that are open or coming.
            GET tournaments() -> Vec<ClashTournament> { path "tournaments"; }
            GET tournament_by_team(team: ClashTeamId) -> Option<ClashTournament> {
                path "tournaments/by-team/{team}";
                status { 404 => None }
            }
            GET tournament(id: ClashTournamentId) -> Option<ClashTournament> {
                path "tournaments/{id}";
                status { 404 => None }
            }
        }

        /// league-v4: LoL's ranked ladders.
        scope league(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/league/v4";

            GET challenger(queue: Queue) -> LeagueList { path "challengerleagues/by-queue/{queue}"; }
            GET grandmaster(queue: Queue) -> LeagueList { path "grandmasterleagues/by-queue/{queue}"; }
            GET master(queue: Queue) -> LeagueList { path "masterleagues/by-queue/{queue}"; }
            GET get(id: LeagueId) -> Option<LeagueList> {
                path "leagues/{id}";
                status { 404 => None }
            }
            /// One entry for each queue the player is ranked in; empty when unranked.
            GET by_puuid(puuid: Puuid) -> Vec<LeagueEntry> { path "entries/by-puuid/{puuid}"; }
            #[deprecated(note = "use by_puuid")]
            GET by_summoner(summoner_id: SummonerId) -> Vec<LeagueEntry> {
                path "entries/by-summoner/{summoner_id}";
            }
            /// A tier and a division below master. (unsure: 205 players a page)
            GET entries(queue: Queue, tier: Tier, division: Division, ..ladder) -> Vec<LeagueEntry> {
                path "entries/{queue}/{tier}/{division}";
            }
        }

        /// league-exp-v4: the same ladder, with master and above.
        scope league_exp(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/league-exp/v4";

            GET entries(queue: Queue, tier: Tier, division: Division, ..ladder) -> Vec<LeagueEntry> {
                path "entries/{queue}/{tier}/{division}";
            }
        }

        /// lol-challenges-v1.
        scope challenges(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/challenges/v1";

            GET config() -> Vec<ChallengeConfig> { path "challenges/config"; }
            /// For each challenge, the share of players at each level.
            GET percentiles() -> HashMap<ChallengeId, Percentiles> { path "challenges/percentiles"; }
            GET challenge_config(id: ChallengeId) -> Option<ChallengeConfig> {
                path "challenges/{id}/config";
                status { 404 => None }
            }
            GET challenge_percentiles(id: ChallengeId) -> Percentiles {
                path "challenges/{id}/percentiles";
            }
            /// The best players at an apex level. Not paged: `limit` is all there is.
            GET leaderboard(id: ChallengeId, level: ApexLevel, limit?: u32) -> Vec<ApexPlayer> {
                path "challenges/{id}/leaderboards/by-level/{level}";
                query { limit; }
            }
            GET player(puuid: Puuid) -> Option<PlayerChallenges> {
                path "player-data/{puuid}";
                status { 404 => None }
            }
        }

        /// spectator-v5. The path says `by-summoner`; it takes a PUUID.
        scope spectator(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/spectator/v5";

            /// `None` when the player is not in a game now.
            GET active_game(puuid: Puuid) -> Option<CurrentGame> {
                path "active-games/by-summoner/{puuid}";
                status { 404 => None }
            }
            GET featured_games() -> FeaturedGames { path "featured-games"; }
        }

        /// spectator-tft-v5: TFT, under a path that starts with `lol`.
        scope spectator_tft(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/spectator/tft/v5";

            /// `None` when the player is not in a game now.
            GET active_game(puuid: Puuid) -> Option<CurrentGame> {
                path "active-games/by-puuid/{puuid}";
                status { 404 => None }
            }
            /// (unsure: the whole endpoint)
            GET featured_games() -> FeaturedGames { path "featured-games"; }
        }

        /// summoner-v4: a player's LoL profile on one platform.
        scope summoner(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "lol/summoner/v4/summoners";

            /// `None` when this account has never played LoL on this platform.
            GET by_puuid(puuid: Puuid) -> Option<Summoner> {
                path "by-puuid/{puuid}";
                status { 404 => None }
            }
            GET me(..player) -> Summoner { path "me"; }
            #[deprecated(note = "use by_puuid")]
            GET by_id(id: SummonerId) -> Option<Summoner> {
                path "{id}";
                status { 404 => None }
            }
            #[deprecated(note = "use by_puuid")]
            GET by_account(account_id: AccountId) -> Option<Summoner> {
                path "by-account/{account_id}";
                status { 404 => None }
            }
            #[deprecated(note = "names became Riot IDs: use account().by_riot_id (unsure: still served)")]
            GET by_name(name: String) -> Option<Summoner> {
                path "by-name/{name}";
                status { 404 => None }
            }
        }

        /// tft-league-v1.
        scope tft_league(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "tft/league/v1";

            GET challenger(..tft_queue) -> TftLeagueList { path "challenger"; }
            GET grandmaster(..tft_queue) -> TftLeagueList { path "grandmaster"; }
            GET master(..tft_queue) -> TftLeagueList { path "master"; }
            GET get(id: LeagueId) -> Option<TftLeagueList> {
                path "leagues/{id}";
                status { 404 => None }
            }
            /// (unsure: the path)
            GET by_puuid(puuid: Puuid) -> Vec<TftLeagueEntry> { path "by-puuid/{puuid}"; }
            #[deprecated(note = "use by_puuid")]
            GET by_summoner(summoner_id: SummonerId) -> Vec<TftLeagueEntry> {
                path "entries/by-summoner/{summoner_id}";
            }
            GET entries(tier: Tier, division: Division, ..tft_queue, ..ladder) -> Vec<TftLeagueEntry> {
                path "entries/{tier}/{division}";
            }
            /// The top of a rated ladder (Hyper Roll). Not paged.
            GET top_rated(queue: RatedQueue) -> Vec<TopRated> { path "rated-ladders/{queue}/top"; }
        }

        /// tft-summoner-v1: the same profile, for TFT.
        scope tft_summoner(route: Platform) {
            base "https://{route}.api.riotgames.com";
            path "tft/summoner/v1/summoners";

            GET by_puuid(puuid: Puuid) -> Option<Summoner> {
                path "by-puuid/{puuid}";
                status { 404 => None }
            }
            GET me(..player) -> Summoner { path "me"; }
            #[deprecated(note = "use by_puuid")]
            GET by_id(id: SummonerId) -> Option<Summoner> {
                path "{id}";
                status { 404 => None }
            }
            #[deprecated(note = "use by_puuid")]
            GET by_account(account_id: AccountId) -> Option<Summoner> {
                path "by-account/{account_id}";
                status { 404 => None }
            }
            #[deprecated(note = "names became Riot IDs: use account().by_riot_id (unsure: still served)")]
            GET by_name(name: String) -> Option<Summoner> {
                path "by-name/{name}";
                status { 404 => None }
            }
        }
    }
}

concord::api! {
    /// Stripe, API v1: customers, payments, refunds, billing, the balance, events, files.
    pub client Stripe(
        /// A secret key (`sk_live_…`, `sk_test_…`) or a restricted one (`rk_…`).
        key: Secret,
        /// A connected account: the request is made as that account (Connect).
        account?: AccountId,
        /// The API version. When it is not given: `API_VERSION`, the one these types were written for.
        version?: String,
    ) {
        base "https://api.stripe.com";
        path "v1";
        headers {
            "authorization" = "Bearer {key}";
            "stripe-version" = version.as_deref().unwrap_or(API_VERSION);
            "stripe-account" = account;
        }
        read Json;
        problem StripeProblem;

        /// Every list: at most `limit` objects, after (or before) the object with a given id.
        part listed(
            /// 1 to 100. Stripe's default is 10.
            limit?: u32,
            /// The id of an object: the page starts after it.
            starting_after?: String,
            /// The id of an object: the page ends before it, and the pages go back in time.
            ending_before?: String,
            /// Created at or after this time (Unix seconds).
            created_gte?: i64,
            /// Created before this time (Unix seconds).
            created_lt?: i64,
        ) {
            query {
                limit; starting_after; ending_before;
                "created[gte]" = created_gte;
                "created[lt]" = created_lt;
            }
            paginate by_object_id(starting_after, ending_before);
        }

        /// Every search: Stripe's query language, in pages by an opaque token.
        /// Not for checking a write: an object is found about a minute after it changed.
        part found(
            /// `email:'ada@example.com'`, `metadata['order']:'7781'`, `status:'succeeded'`.
            query: String,
            /// 1 to 100. Stripe's default is 10.
            limit?: u32,
            /// The `next_page` of the page before.
            page?: String,
        ) {
            query { query; limit; page; }
            paginate by_cursor(page, SearchResult::next_token);
        }

        /// What a `GET` or a `DELETE` expands: in the query.
        part expanded(
            /// Ids in the answer to give as whole objects: `customer`; in a list, `data.customer`.
            expand?: Vec<String>,
        ) {
            query { "expand[]" = expand; }
        }

        /// Every `POST`. A `POST` sends `expand` in its form body, which a part cannot reach:
        /// each node names `expand` in its own `body`.
        part write(
            /// The same key gives the same answer for at least 24 hours. Give one to send an operation
            /// again after a crash; without one, a key is made for the call, and every try sends it.
            idempotency_key?: String,
            /// As in `expanded`, but sent in the body.
            expand?: Vec<String>,
        ) {
            headers { "idempotency-key" = idempotency_key.clone().unwrap_or_else(new_idempotency_key); }
            idempotent;
        }

        scope customers {
            path "customers";

            POST create(customer: NewCustomer, ..write) -> Customer { body stripe_form(customer, expand); }
            /// `None` when the customer was deleted: Stripe answers `200` with `deleted: true`.
            /// An id that never existed is still a `404`.
            GET retrieve(id: CustomerId, ..expanded) -> Option<Customer> {
                path "{id}";
                status { 200 { body } => MaybeDeleted::live(body) }
            }
            POST update(id: CustomerId, changes: UpdateCustomer, ..write) -> Customer {
                path "{id}";
                body stripe_form(changes, expand);
            }
            DELETE delete(id: CustomerId) -> Deleted<CustomerId> { path "{id}"; }
            GET list(email?: String, ..listed, ..expanded) -> List<Customer> { query { email; } }
            GET search(..found, ..expanded) -> SearchResult<Customer> { path "search"; }
        }

        scope payment_intents {
            path "payment_intents";

            POST create(intent: NewPaymentIntent, ..write) -> PaymentIntent { body stripe_form(intent, expand); }
            GET retrieve(id: PaymentIntentId, ..expanded) -> PaymentIntent { path "{id}"; }
            POST update(id: PaymentIntentId, changes: UpdatePaymentIntent, ..write) -> PaymentIntent {
                path "{id}";
                body stripe_form(changes, expand);
            }
            /// `Err` when the card was declined (`402`); the intent is in `error.payment_intent`.
            /// An `Ok` may still wait for the customer: look at `status` and `next_action`.
            POST confirm(id: PaymentIntentId, params?: ConfirmPaymentIntent, ..write) -> Result<PaymentIntent, Declined> {
                path "{id}/confirm";
                body stripe_form(params, expand);
                status { 402 { body } => Err(body) }
            }
            POST capture(id: PaymentIntentId, params?: CapturePaymentIntent, ..write) -> PaymentIntent {
                path "{id}/capture";
                body stripe_form(params, expand);
            }
            POST cancel(id: PaymentIntentId, params?: CancelPaymentIntent, ..write) -> PaymentIntent {
                path "{id}/cancel";
                body stripe_form(params, expand);
            }
            GET list(customer?: CustomerId, ..listed, ..expanded) -> List<PaymentIntent> { query { customer; } }
            GET search(..found, ..expanded) -> SearchResult<PaymentIntent> { path "search"; }
        }

        scope refunds {
            path "refunds";

            /// The body names the payment: `payment_intent` or `charge`.
            POST create(refund: NewRefund, ..write) -> Refund { body stripe_form(refund, expand); }
            GET retrieve(id: RefundId, ..expanded) -> Refund { path "{id}"; }
            POST update(id: RefundId, changes: UpdateRefund, ..write) -> Refund {
                path "{id}";
                body stripe_form(changes, expand);
            }
            /// Only a refund whose status is `requires_action`.
            POST cancel(id: RefundId, ..write) -> Refund {
                path "{id}/cancel";
                body stripe_form(&(), expand);
            }
            GET list(charge?: ChargeId, payment_intent?: PaymentIntentId, ..listed, ..expanded) -> List<Refund> {
                query { charge; payment_intent; }
            }
        }

        scope subscriptions {
            path "subscriptions";

            POST create(subscription: NewSubscription, ..write) -> Subscription { body stripe_form(subscription, expand); }
            GET retrieve(id: SubscriptionId, ..expanded) -> Subscription { path "{id}"; }
            POST update(id: SubscriptionId, changes: UpdateSubscription, ..write) -> Subscription {
                path "{id}";
                body stripe_form(changes, expand);
            }
            /// Cancels now. To cancel at the end of the period: `update` with `cancel_at_period_end`.
            /// The options of a `DELETE` go in the query (unsure).
            DELETE cancel(id: SubscriptionId, invoice_now?: bool, prorate?: bool, ..expanded) -> Subscription {
                path "{id}";
                query { invoice_now; prorate; }
            }
            /// With no `status`, every subscription that is not canceled.
            GET list(customer?: CustomerId, price?: PriceId, status?: SubscriptionFilter, ..listed, ..expanded) -> List<Subscription> {
                query { customer; price; status; }
            }
        }

        scope invoices {
            path "invoices";

            POST create(invoice: NewInvoice, ..write) -> Invoice { body stripe_form(invoice, expand); }
            GET retrieve(id: InvoiceId, ..expanded) -> Invoice { path "{id}"; }
            POST update(id: InvoiceId, changes: UpdateInvoice, ..write) -> Invoice {
                path "{id}";
                body stripe_form(changes, expand);
            }
            /// Only a draft. An invoice that was finalized is voided instead.
            DELETE delete(id: InvoiceId) -> Deleted<InvoiceId> { path "{id}"; }
            GET list(
                customer?: CustomerId,
                subscription?: SubscriptionId,
                status?: InvoiceStatus,
                collection_method?: CollectionMethod,
                ..listed,
                ..expanded
            ) -> List<Invoice> {
                query { customer; subscription; status; collection_method; }
            }
            POST finalize(id: InvoiceId, params?: FinalizeInvoice, ..write) -> Invoice {
                path "{id}/finalize";
                body stripe_form(params, expand);
            }
            /// `Err` when the payment was declined (`402`).
            POST pay(id: InvoiceId, params?: PayInvoice, ..write) -> Result<Invoice, Declined> {
                path "{id}/pay";
                body stripe_form(params, expand);
                status { 402 { body } => Err(body) }
            }
            POST void(id: InvoiceId, ..write) -> Invoice {
                path "{id}/void";
                body stripe_form(&(), expand);
            }
            POST mark_uncollectible(id: InvoiceId, ..write) -> Invoice {
                path "{id}/mark_uncollectible";
                body stripe_form(&(), expand);
            }
            /// Emails the invoice to the customer. (Stripe's libraries call it `send_invoice`,
            /// a name that Concord keeps for itself.)
            POST send(id: InvoiceId, ..write) -> Invoice {
                path "{id}/send";
                body stripe_form(&(), expand);
            }
        }

        /// What the account holds: available and pending, by currency.
        GET balance() -> Balance { path "balance"; }

        scope balance_transactions {
            path "balance_transactions";

            GET retrieve(id: BalanceTransactionId, ..expanded) -> BalanceTransaction { path "{id}"; }
            GET list(
                payout?: PayoutId,
                source?: String,
                /// `charge`, `refund`, `payout`, … (Stripe's `type`).
                kind?: String,
                currency?: Currency,
                ..listed,
                ..expanded
            ) -> List<BalanceTransaction> {
                query { payout; source; "type" = kind; currency; }
            }
        }

        /// Kept 30 days. `data.object` is written in the API version of the time it happened.
        scope events {
            path "events";

            GET retrieve(id: EventId) -> Event { path "{id}"; }
            GET list(
                /// One type, or a family: `invoice.*` (Stripe's `type`).
                kind?: String,
                /// Up to 20 types.
                types?: Vec<String>,
                delivery_success?: bool,
                ..listed
            ) -> List<Event> {
                query { "type" = kind; "types[]" = types; delivery_success; }
            }
        }

        /// A file, on the files host: dispute evidence, an identity document, a logo.
        /// The bytes are held in memory, so a second try sends them again, with the same key.
        POST create_file(purpose: FilePurpose, file: Upload, ..write) -> StripeFile {
            base "https://files.stripe.com";
            path "files";
            headers { override "authorization" = "Bearer {client.key}"; }
            body multipart(purpose, file, expand);
        }
    }
}

concord::api! {
    pub client Github(user_agent: String, quota: QuotaLog, token?: Secret) {
        base "https://api.github.com";
        headers {
            "user-agent" = user_agent;
            "accept" = "application/vnd.github+json";
            "x-github-api-version" = "2026-03-10";
            "authorization" = "Bearer {token}";
        }
        read Json;
        problem GithubProblem;
        /// Records rate-limit headers on every response, including each page and try.
        middleware ObserveQuota(quota.clone());

        part page(per_page?: u32, page?: u32) {
            query { per_page; page; }
            paginate by_link();
        }
        part repo_order(sort?: RepoSort, direction?: Direction) {
            query { sort; direction; }
        }
        part at_ref(reference?: String) {
            query { "ref" = reference; }
        }

        GET rate_limit() -> RateLimits { path "rate_limit"; }
        GET repository(id: u64) -> Repository { path "repositories/{id}"; }

        scope user {
            path "user";
            GET get() -> User;
            /// kind cannot accompany visibility or affiliation.
            GET repos(
                visibility?: Visibility, affiliation?: Vec<String>,
                kind?: UserRepoType, since?: String, before?: String,
                ..repo_order, ..page
            ) -> Vec<Repository> {
                path "repos";
                query {
                    visibility;
                    "affiliation" = affiliation.as_ref().map(|v| v.join(","));
                    "type" = checked_repo_kind(kind, visibility, affiliation)?;
                    since; before;
                }
            }
            POST create_repo(repo: NewRepository) -> Repository {
                path "repos";
                body json(repo);
            }
        }

        scope users(username: String) {
            path "users/{username}";
            GET get() -> User;
            GET repos(kind?: PublicRepoType, ..repo_order, ..page) -> Vec<Repository> {
                path "repos";
                query { "type" = kind; }
            }
        }

        scope orgs(org: String) {
            path "orgs/{org}";
            GET repos(kind?: OrgRepoType, ..repo_order, ..page) -> Vec<Repository> {
                path "repos";
                query { "type" = kind; }
            }
            POST create_repo(repo: NewRepository) -> Repository {
                path "repos";
                body json(repo);
            }
        }

        scope repo(owner: String, name: String) {
            path "repos/{owner}/{name}";
            /// A renamed repository's 301 remains an error with Location; see get_with_moves.
            GET get() -> Repository;
            /// Compatibility alias for this inventory; get().send_if_none_match(etag) also works.
            GET get_if_changed(etag: String) -> Option<Repository> {
                headers { "if-none-match" = etag; }
                status { 304 => None }
            }
            /// None means calculation pending, not an absent repository.
            GET contributor_stats() -> Option<Vec<ContributorStats>> {
                path "stats/contributors";
                status { 202 => None, 204 => Some(Vec::new()) }
            }
            /// A root directory is not a paginated list.
            GET contents_root(..at_ref) -> Vec<ContentEntry> { path "contents"; }

            scope issues {
                path "issues";
                /// Includes pull requests. milestone/assignee/kind accept "*" and "none".
                /// since is UTC ISO 8601; labels is an AND filter.
                GET list(
                    milestone?: String, state?: IssueState, assignee?: String,
                    kind?: String, creator?: String, mentioned?: String,
                    issue_field_values?: String, labels?: Vec<String>,
                    sort?: IssueSort, direction?: Direction, since?: String,
                    ..page
                ) -> Vec<Issue> {
                    query {
                        milestone; state; assignee; "type" = kind; creator; mentioned;
                        issue_field_values;
                        "labels" = labels.as_ref().map(|v| v.join(","));
                        sort; direction; since;
                    }
                }
                POST create(issue: NewIssue) -> Issue { body json(issue); }

                scope comment(id: u64) {
                    path "comments/{id}";
                    GET get() -> Comment;
                    PATCH update(body: String) -> Comment {
                        body json(serde_json::json!({ "body": body }));
                    }
                    DELETE delete();
                }

                scope issue(number: u64) {
                    path "{number}";
                    GET get() -> Issue;
                    PATCH update(changes: EditIssue) -> Issue { body json(changes); }
                    GET comments(since?: String, ..page) -> Vec<Comment> {
                        path "comments";
                        query { since; }
                    }
                    POST create_comment(body: String) -> Comment {
                        path "comments";
                        body json(serde_json::json!({ "body": body }));
                    }
                }
            }

            scope pulls {
                path "pulls";
                GET list(
                    state?: IssueState, head?: String, base?: String,
                    sort?: PullSort, direction?: Direction, ..page
                ) -> Vec<Pull> {
                    query { state; head; base; sort; direction; }
                }
                POST create(pull: NewPull) -> Pull { body json(pull); }

                scope pull(number: u64) {
                    path "{number}";
                    GET get() -> Pull;
                    GET diff() -> Bytes {
                        headers { override "accept" = "application/vnd.github.diff"; }
                        read Binary;
                    }
                    GET files(..page) -> Vec<PullFile> { path "files"; }
                    /// 404 here is GitHub's negative answer; inaccessible resources can also hide.
                    GET is_merged() -> bool {
                        path "merge";
                        status { 204 => true, 404 => false }
                    }
                    PUT merge(options: MergePull) -> MergeResult {
                        path "merge";
                        body json(options);
                        idempotent false;
                    }
                }
            }

            scope contents(path: String) {
                path "contents/{*path}";
                GET get(..at_ref) -> Contents;
                /// Files, including symlinks resolved to files; bytes need not be UTF-8.
                GET raw(..at_ref) -> Bytes {
                    headers { override "accept" = "application/vnd.github.raw+json"; }
                    read Binary.limit(100 * concord::MIB);
                }
                /// content is base64; sha is required when replacing an existing file.
                PUT create_or_update(change: PutContent) -> ContentWrite {
                    body json(change);
                    idempotent false;
                }
            }

            scope releases {
                path "releases";
                GET list(..page) -> Vec<Release>;
                POST create(release: NewRelease) -> Release { body json(release); }
                GET latest() -> Release { path "latest"; }
                GET by_tag(tag: String) -> Release { path "tags/{tag}"; }

                scope release(id: u64) {
                    path "{id}";
                    GET get() -> Release;
                    DELETE delete();
                    GET assets(..page) -> Vec<Asset> { path "assets"; }
                    /// Body carries its media type; size also permits a known-length stream.
                    POST asset(
                        name: String, file: concord::Body, size: u64, label?: String
                    ) -> Asset {
                        base "https://uploads.github.com";
                        path "assets";
                        headers {
                            override "authorization" = "Bearer {client.token}";
                            "content-length" = size;
                        }
                        query { name; label; }
                        body file;
                    }
                }
            }
        }

        scope search {
            path "search";
            /// q is unencoded GitHub search text. Sorting words belong to GitHub.
            GET repositories(q: String, sort?: String, order?: Direction, ..page)
                -> SearchPage<Repository> {
                path "repositories";
                query { q; sort; order; }
            }
            GET issues(q: String, sort?: String, order?: Direction, ..page)
                -> SearchPage<Issue> {
                path "issues";
                query { q; sort; order; }
            }
        }
    }
}

concord::api! {
    pub client ObjectStore(region: String, credentials: Credentials) {
        read Xml;
        problem crate::model::S3Problem;
        /// Signs every request, including each page and every retry.
        middleware Signed::new(credentials.clone(), region.clone());

        part version(version_id?: String) {
            query { "versionId" = version_id; }
        }
        part conditions(
            if_match?: String,
            if_modified_since?: String,
            if_unmodified_since?: String,
        ) {
            headers {
                "if-match" = if_match;
                "if-modified-since" = if_modified_since;
                "if-unmodified-since" = if_unmodified_since;
            }
        }
        part write_headers(
            content_type?: String,
            cache_control?: String,
            storage_class?: String,
        ) {
            headers {
                "content-type" = content_type;
                "cache-control" = cache_control;
                "x-amz-storage-class" = storage_class;
            }
        }
        part listing(prefix?: String, delimiter?: String) {
            query { prefix; delimiter; }
        }

        GET list_buckets(
            max_buckets?: u32, continuation_token?: String, prefix?: String,
        ) -> BucketsPage {
            base "https://s3.amazonaws.com";
            query {
                "max-buckets" = max_buckets;
                "continuation-token" = continuation_token;
                prefix;
            }
            paginate by_cursor(continuation_token, BucketsPage::next);
        }

        scope bucket(url: Base) {
            base url;

            /// Failure preserves the status and region header; 404 is not a boolean.
            HEAD head();
            /// Omit configuration in us-east-1; elsewhere give LocationConstraint.
            PUT create(configuration?: CreateBucketConfiguration) {
                body create_bucket_body(configuration);
                idempotent false;
            }
            DELETE delete();

            GET list_objects(
                max_keys?: u32, continuation_token?: String,
                start_after?: String, fetch_owner?: bool, ..listing,
            ) -> ObjectsPage {
                query {
                    "list-type" = "2";
                    "encoding-type" = "url";
                    "max-keys" = max_keys;
                    "continuation-token" = continuation_token;
                    "start-after" = start_after;
                    "fetch-owner" = fetch_owner;
                }
                paginate checked_cursor(continuation_token, ObjectsPage::next);
            }
            /// Per-key failures remain in DeleteResult, even on HTTP 200.
            POST delete_objects(batch: DeleteBatch) -> DeleteResult {
                query { "delete" = ""; }
                body crate::wire::xml(batch);
            }
            GET list_multipart_uploads(
                max_uploads?: u32, key_marker?: String,
                upload_id_marker?: String, ..listing,
            ) -> UploadsPage {
                query {
                    "uploads" = "";
                    "encoding-type" = "url";
                    "max-uploads" = max_uploads;
                    "key-marker" = key_marker;
                    "upload-id-marker" = upload_id_marker;
                }
                paginate uploads_after(key_marker, upload_id_marker);
            }

            scope object(key: String) {
                path "{*key}";

                GET get(range?: String, ..version, ..conditions) -> ByteStream {
                    headers { "range" = range; }
                    read Stream;
                }
                GET get_if_changed(
                    etag: String, range?: String, ..version, ..conditions,
                ) -> Option<ByteStream> {
                    headers { "if-none-match" = etag; "range" = range; }
                    read Stream;
                    status { 304 => None }
                }
                HEAD head(..version, ..conditions) -> http::HeaderMap {
                    status { 2xx { headers } => headers.as_map().clone() }
                }
                /// ETag is the value; send_full also keeps version/checksum headers.
                PUT put(file: Body, size: u64, ..write_headers) -> String {
                    headers { "content-length" = size; }
                    body file;
                    status { 2xx { headers } => headers.require("etag")?.to_owned() }
                    idempotent false;
                }
                PUT copy_from(
                    source_bucket: String, source_key: String,
                    source_version?: String, source_if_match?: String,
                    metadata_directive?: String, ..write_headers,
                ) -> CopyResult {
                    headers {
                        "x-amz-copy-source" = copy_source(source_bucket, source_key, source_version);
                        "x-amz-copy-source-if-match" = source_if_match;
                        "x-amz-metadata-directive" = metadata_directive;
                    }
                    status { 2xx { body } => copy_ok(body)? }
                    idempotent false;
                }
                DELETE delete(..version) {
                    idempotent version_id.as_ref().is_some_and(|id| id != "null");
                }
                POST create_multipart_upload(..write_headers) -> InitiatedUpload {
                    query { "uploads" = ""; }
                }

                scope upload(upload_id: String) {
                    query { "uploadId" = upload_id; }

                    PUT upload_part(part_number: u32, file: Body, size: u64) -> String {
                        query { "partNumber" = part_number; }
                        headers { "content-length" = size; }
                        body file;
                        status { 2xx { headers } => headers.require("etag")?.to_owned() }
                    }
                    POST complete(parts: CompleteUpload) -> CompleteResult {
                        body crate::wire::xml(parts);
                        status { 2xx { body } => complete_ok(body)? }
                    }
                    DELETE abort();
                    GET list_parts(
                        max_parts?: u32, part_number_marker?: u32,
                    ) -> PartsPage {
                        query {
                            "max-parts" = max_parts;
                            "part-number-marker" = part_number_marker;
                        }
                        paginate checked_cursor(part_number_marker, PartsPage::next);
                    }
                }
            }
        }
    }
}

concord::api! {
    /// The Slack Web API: one method is one URL, `https://slack.com/api/<family>.<method>`.
    /// Every answer is a `200`; `{ "ok": false, "error": "…" }` is a refusal.
    pub client Slack(
        /// A bot (`xoxb-…`) or a user (`xoxp-…`) token.
        token: Secret,
    ) {
        base "https://slack.com/api";                 // `/api` here: a `path` would follow the upload host
        headers { "authorization" = "Bearer {token}"; }
        read Json;
        problem SlackProblem;
        status { 2xx { body } => Reply::into_result(body)? }     // `ok: false` is a Refused error

        /// Slack's cursor: the next one is `response_metadata.next_cursor`, empty at the end.
        part page(cursor?: String, limit?: u32) {
            query { cursor; limit; }
            paginate by_cursor(cursor, next_cursor);
        }

        scope auth {
            /// Who this token is: the team, the user, the bot.
            GET test() -> Identity { path "auth.test"; }
        }

        scope conversations {
            /// The conversations the token can see. `types` goes as one comma list.
            GET list(
                exclude_archived?: bool,
                types?: Vec<ConversationType>,
                team_id?: TeamId,
                ..page
            ) -> ChannelList {
                path "conversations.list";
                query { exclude_archived; "types" = types.as_ref().map(|t| comma(t)); team_id; }
            }

            /// The messages of a conversation, newest first.
            GET history(
                channel: ChannelId,
                oldest?: Ts,
                latest?: Ts,
                inclusive?: bool,
                include_all_metadata?: bool,
                ..page
            ) -> MessageList {
                path "conversations.history";
                query { channel; oldest; latest; inclusive; include_all_metadata; }
            }

            GET info(channel: ChannelId, include_locale?: bool, include_num_members?: bool) -> ChannelInfo {
                path "conversations.info";
                query { channel; include_locale; include_num_members; }
            }

            /// Joins a public channel. Joining again changes nothing (Slack adds a warning).
            POST join(channel: ChannelId) -> ChannelInfo {
                path "conversations.join";
                body slack_json(json!({ "channel": channel }));
                idempotent;
            }
        }

        scope chat {
            /// Slack wants `text` or `blocks` (else `no_text`).
            POST post_message(
                channel: ChannelId,
                text?: String,
                blocks?: Vec<Block>,
                thread_ts?: Ts,
                reply_broadcast?: bool,
                unfurl_links?: bool,
                unfurl_media?: bool,
                metadata?: Metadata,
            ) -> Posted {
                path "chat.postMessage";
                body slack_json(json!({
                    "channel": channel, "text": text, "blocks": blocks, "thread_ts": thread_ts,
                    "reply_broadcast": reply_broadcast, "unfurl_links": unfurl_links,
                    "unfurl_media": unfurl_media, "metadata": metadata,
                }));
            }

            /// The same update twice gives the same message.
            POST update(channel: ChannelId, ts: Ts, text?: String, blocks?: Vec<Block>) -> Updated {
                path "chat.update";
                body slack_json(json!({ "channel": channel, "ts": ts, "text": text, "blocks": blocks }));
                idempotent;
            }

            POST delete(channel: ChannelId, ts: Ts) -> Deleted {
                path "chat.delete";
                body slack_json(json!({ "channel": channel, "ts": ts }));
            }
        }

        scope reactions {
            /// `name` is the emoji without colons; `timestamp` is the `ts` of the message.
            POST add(channel: ChannelId, timestamp: Ts, name: String) -> Done {
                path "reactions.add";
                body slack_json(json!({ "channel": channel, "timestamp": timestamp, "name": name }));
            }
        }

        scope users {
            GET list(include_locale?: bool, team_id?: TeamId, ..page) -> UserList {
                path "users.list";
                query { include_locale; team_id; }
            }

            GET info(user: UserId, include_locale?: bool) -> UserInfo {
                path "users.info";
                query { user; include_locale; }
            }
        }

        scope files {
            /// Upload, step 1: where to send `length` bytes. A form, not JSON (unsure).
            POST get_upload_url_external(
                filename: String,
                length: u64,
                alt_txt?: String,
                snippet_type?: String,
            ) -> UploadTicket {
                path "files.getUploadURLExternal";
                body slack_form(json!({
                    "filename": filename, "length": length, "alt_txt": alt_txt, "snippet_type": snippet_type,
                }));
            }

            /// Upload, step 2: the bytes, to the `upload_url` of step 1. Another host, no token,
            /// and the answer is text (`OK - 1234`), not Slack's JSON (unsure).
            POST upload(upload_url: concord::Base, file: concord::Body) {
                base upload_url;
                headers { remove "authorization"; }
                status { remove 2xx }
                body file;
            }

            /// Upload, step 3: the files are shared, in a channel when `channel_id` is given.
            POST complete_upload_external(
                uploaded: Vec<FileRef>,                   // Slack's `files`: the name of this scope
                channel_id?: ChannelId,
                initial_comment?: String,
                thread_ts?: Ts,
            ) -> Completed {
                path "files.completeUploadExternal";
                body slack_json(json!({
                    "files": uploaded, "channel_id": channel_id,
                    "initial_comment": initial_comment, "thread_ts": thread_ts,
                }));
            }
        }

        scope views {
            /// A modal. `trigger_id` comes from an interaction, lives 3 seconds, and is used once.
            POST open(trigger_id: String, view: View) -> Opened {
                path "views.open";
                body slack_json(json!({ "trigger_id": trigger_id, "view": view }));
            }
        }
    }
}

concord::api! {
    /// The Telegram Bot API: twelve of its methods, and the download of a file.
    pub client Telegram(
        /// The bot's token from @BotFather (`123456:ABC-…`). Telegram wants it in the path.
        token: Secret,
    ) {
        base "https://api.telegram.org/bot{token}";
        read Json;
        problem TgProblem;
        status { 2xx { body } => Reply::into_result(body)? }        // `{ "ok": true, "result": … }`

        /// How a text is formatted: one of the two.
        part formatted(parse_mode?: ParseMode, entities?: Vec<MessageEntity>) {}

        /// What a new message may say about how it is delivered.
        part delivery(
            message_thread_id?: i64,
            disable_notification?: bool,
            protect_content?: bool,
            reply_parameters?: ReplyParameters,
            reply_markup?: ReplyMarkup,
        ) {}

        /// The bot itself.
        GET get_me() -> User { path "getMe"; }

        /// New updates, oldest first. While there is none, the server holds the request up to
        /// `timeout` seconds: send it with `.long_poll(seconds)`, which sets Concord's clock too.
        GET get_updates(offset?: i64, limit?: u32, timeout?: u32, allowed_updates?: Vec<UpdateKind>) -> Vec<Update> {
            path "getUpdates";
            query { offset; limit; timeout; "allowed_updates" = allowed_updates.as_ref().map(AsJson); }
        }

        /// `sendMessage` (`send_message` is a name that Concord keeps).
        POST post_message(chat_id: ChatId, text: String, link_preview_options?: LinkPreviewOptions,
                          ..formatted, ..delivery) -> Message {
            path "sendMessage";
            body params(json!({
                "chat_id": chat_id, "text": text, "link_preview_options": link_preview_options,
                "parse_mode": parse_mode, "entities": entities,
                "message_thread_id": message_thread_id, "disable_notification": disable_notification,
                "protect_content": protect_content, "reply_parameters": reply_parameters,
                "reply_markup": reply_markup
            }));
        }

        /// `sendPhoto`: a `file_id`, a URL that Telegram fetches, or bytes.
        POST post_photo(chat_id: ChatId, photo: InputFile, caption?: String, ..formatted, ..delivery) -> Message {
            path "sendPhoto";
            body upload("photo", photo, json!({
                "chat_id": chat_id, "caption": caption,
                "parse_mode": parse_mode, "caption_entities": entities,
                "message_thread_id": message_thread_id, "disable_notification": disable_notification,
                "protect_content": protect_content, "reply_parameters": reply_parameters,
                "reply_markup": reply_markup
            }));
        }

        /// `sendDocument`: the same three ways. (`thumbnail` is left out.)
        POST post_document(chat_id: ChatId, document: InputFile, caption?: String,
                           disable_content_type_detection?: bool, ..formatted, ..delivery) -> Message {
            path "sendDocument";
            body upload("document", document, json!({
                "chat_id": chat_id, "caption": caption,
                "disable_content_type_detection": disable_content_type_detection,
                "parse_mode": parse_mode, "caption_entities": entities,
                "message_thread_id": message_thread_id, "disable_notification": disable_notification,
                "protect_content": protect_content, "reply_parameters": reply_parameters,
                "reply_markup": reply_markup
            }));
        }

        /// `editMessageText` for a message in a chat: the message as it is now.
        POST edit_message_text(chat_id: ChatId, message_id: i64, text: String,
                               reply_markup?: InlineKeyboardMarkup, ..formatted) -> Message {
            path "editMessageText";
            body params(json!({
                "chat_id": chat_id, "message_id": message_id, "text": text, "reply_markup": reply_markup,
                "parse_mode": parse_mode, "entities": entities
            }));
        }

        /// `editMessageText` for a message that was sent inline: Telegram answers `true`.
        POST edit_inline_message_text(inline_message_id: String, text: String,
                                      reply_markup?: InlineKeyboardMarkup, ..formatted) -> bool {
            path "editMessageText";
            body params(json!({
                "inline_message_id": inline_message_id, "text": text, "reply_markup": reply_markup,
                "parse_mode": parse_mode, "entities": entities
            }));
        }

        /// `true`. Most messages can be deleted only in their first 48 hours (unsure of every case).
        POST delete_message(chat_id: ChatId, message_id: i64) -> bool {
            path "deleteMessage";
            body params(json!({ "chat_id": chat_id, "message_id": message_id }));
        }

        /// Ends the wait on an inline button; `text` shows as a notice, or as an alert.
        POST answer_callback_query(callback_query_id: String, text?: String, show_alert?: bool,
                                   url?: String, cache_time?: u32) -> bool {
            path "answerCallbackQuery";
            body params(json!({
                "callback_query_id": callback_query_id, "text": text, "show_alert": show_alert,
                "url": url, "cache_time": cache_time
            }));
        }

        /// A chat, with everything that Telegram tells a bot about it.
        GET get_chat(chat_id: ChatId) -> ChatFullInfo {
            path "getChat";
            query { chat_id; }
        }

        /// Where a file is: its `file_path`, good for at least an hour. 20 MB at most.
        GET get_file(file_id: String) -> File {
            path "getFile";
            query { file_id; }
        }

        /// The bytes of a file, from the `file_path` of `get_file`: another path on the same host.
        GET download(file_path: String) -> ByteStream {
            base "https://api.telegram.org/file/bot{client.token}";
            path "{*file_path}";
            read Stream;
            status { remove 2xx }                                    // the bytes are not `{ "ok": … }`
        }

        /// Updates go to `url`, and `get_updates` answers `409`. (`certificate`, `ip_address` left out.)
        POST set_webhook(url: String, secret_token?: Secret, max_connections?: u32,
                         allowed_updates?: Vec<UpdateKind>, drop_pending_updates?: bool) -> bool {
            path "setWebhook";
            body params(json!({
                "url": url, "secret_token": secret_token, "max_connections": max_connections,
                "allowed_updates": allowed_updates, "drop_pending_updates": drop_pending_updates
            }));
            idempotent drop_pending_updates != &Some(true);          // a second drop loses what came between
        }

        /// Back to `get_updates`.
        POST delete_webhook(drop_pending_updates?: bool) -> bool {
            path "deleteWebhook";
            body params(json!({ "drop_pending_updates": drop_pending_updates }));
            idempotent drop_pending_updates != &Some(true);
        }
    }
}

concord::api! {
    pub client Kubernetes(cluster: Base, token: Secret) {
        base cluster;
        headers { "authorization" = "Bearer {token}"; "accept" = "application/json"; }
        read Json;
        problem Status;
        /// Reports the API server's Warning headers, including on each page and try.
        middleware KubeWarnings;

        part selectors(label_selector?: String, field_selector?: String) {
            query { "labelSelector" = label_selector; "fieldSelector" = field_selector; }
        }
        part page(limit?: u32, continuation?: String,
                  resource_version?: String, resource_version_match?: String) {
            query {
                limit; "continue" = continuation;
                "resourceVersion" = resource_version; "resourceVersionMatch" = resource_version_match;
            }
            paginate move |call, answer| answer.value().next_token().map(|next| {
                call.continuation(next).resource_version(None::<String>)
                    .resource_version_match(None::<String>)
            });
        }
        part watching(resource_version?: String, allow_watch_bookmarks?: bool, timeout_seconds?: u32) {
            query {
                "watch" = true; "resourceVersion" = resource_version;
                "allowWatchBookmarks" = allow_watch_bookmarks; "timeoutSeconds" = timeout_seconds;
            }
            read Stream;
        }
        part writing(dry_run?: String) {
            query { "dryRun" = dry_run; }
        }

        scope pods {
            path "api/v1/pods";
            GET list(..selectors, ..page) -> KubeList<Pod>;
            /// One connection; EOF and an ERROR record require an application decision.
            GET watch(..selectors, ..watching) -> ByteStream;
        }
        scope namespaces(namespace: String) {
            path "api/v1/namespaces/{namespace}";
            scope pods {
                path "pods";
                GET list(..selectors, ..page) -> KubeList<Pod>;
                GET get(name: String, resource_version?: String) -> Pod {
                    path "{name}";
                    query { "resourceVersion" = resource_version; }
                }
                POST create(pod: Pod, ..writing) -> Pod { body json(pod); }
                PUT replace(name: String, pod: Pod, ..writing) -> Pod {
                    path "{name}";
                    body json(pod);
                }
                /// Success acknowledges deletion; finalizers may keep the Pod alive.
                DELETE delete(name: String, options: DeleteOptions, ..writing) {
                    path "{name}";
                    body json(options);
                    idempotent false;
                }
                PATCH patch_json(name: String, patch: Vec<Value>, ..writing) -> Pod {
                    path "{name}";
                    headers { "content-type" = "application/json-patch+json"; }
                    body json(patch);
                }
                PATCH patch_merge(name: String, patch: Value, ..writing) -> Pod {
                    path "{name}";
                    headers { "content-type" = "application/merge-patch+json"; }
                    body json(patch);
                }
                PATCH patch_strategic(name: String, patch: Value, ..writing) -> Pod {
                    path "{name}";
                    headers { "content-type" = "application/strategic-merge-patch+json"; }
                    body json(patch);
                }
                GET watch(..selectors, ..watching) -> ByteStream;
                GET log(name: String, container?: String, follow?: bool,
                        previous?: bool, tail_lines?: i64, timestamps?: bool) -> ByteStream {
                    path "{name}/log";
                    query { container; follow; previous; "tailLines" = tail_lines; timestamps; }
                    headers { override "accept" = "text/plain"; }
                    read Stream;
                }
            }
        }
        scope deployments(namespace: String, name: String) {
            path "apis/apps/v1/namespaces/{namespace}/deployments/{name}";
            GET status() -> Deployment { path "status"; }
            GET scale() -> Scale { path "scale"; }
        }
        /// Requires the namespaced CronTab CRD from the Kubernetes documentation.
        GET get_crontab(namespace: String, name: String) -> CronTab {
            path "apis/stable.example.com/v1/namespaces/{namespace}/crontabs/{name}";
        }
    }
}

concord::api! {
    pub client Elasticsearch(url: Base, bulk_url: Base, authorization: Secret) {
        base url;
        headers { "authorization" = authorization; }
        read Json;
        problem EsProblem;
        /// Logs endpoint names and try numbers, never payloads or credentials.
        middleware TraceRequests;

        part output(pretty?: bool, filter_path?: Vec<String>) {
            query { pretty; "filter_path" = filter_path.as_ref().map(|p| p.join(",")); }
        }
        part write_options(refresh?: Refresh, routing?: String) {
            query { refresh; routing; }
        }

        /// One index or single-index alias; not a wildcard or comma list.
        scope index(name: String) {
            path "{name}";
            PUT index_document(id: String, document: Value, ..output, ..write_options) -> WriteReply {
                path "_doc/{id}";
                body json(document);
                idempotent false;
            }
            POST index_auto(document: Value, ..output, ..write_options) -> WriteReply {
                path "_doc";
                body json(document);
            }
            GET get(id: String, ..output) -> GetReply {
                path "_doc/{id}";
                status { 404 { body } => document_404::<GetReply>(body)? }
            }
            HEAD exists(id: String, ..output) -> bool {
                path "_doc/{id}";
                status { 2xx => true, 404 => false }
            }
            /// Patch is an update envelope: doc, script, upsert, etc.
            POST update(id: String, patch: Value, ..output, ..write_options) -> WriteReply {
                path "_update/{id}";
                body json(patch);
            }
            DELETE delete_document(id: String, ..output, ..write_options) -> WriteReply {
                path "_doc/{id}";
                status { 404 { body } => document_404::<WriteReply>(body)? }
                idempotent false;
            }
            PUT create(settings: Value, ..output) -> IndexAck {
                body json(settings);
                idempotent false;
            }
            DELETE delete(..output) -> IndexAck { idempotent false; }
        }

        /// A comma list and/or wildcard expression, kept in one path segment.
        scope indices(targets: String) {
            path "{targets}";
            GET search(request: Value, ..output) -> SearchPage {
                path "_search";
                body json(request);
                idempotent;
            }
            GET count(request: Value, ..output) -> CountReply {
                path "_count";
                body json(request);
            }
            POST open_pit(keep_alive: String, ..output) -> OpenedPit {
                path "_pit";
                query { keep_alive; }
            }
        }

        POST bulk(lines: Vec<Value>, ..output, ..write_options) -> BulkReply {
            base client.bulk_url;
            headers { override "authorization" = client.authorization; }
            path "_bulk";
            body ndjson(lines);
        }
        /// No index in the URL. Cursor replaces both PIT id and search_after.
        /// filter_path is deliberately unavailable: the pager needs its fields.
        POST search_pit(query: Value, pit_id: String, keep_alive: String,
                        size?: u32, cursor?: PitCursor, pretty?: bool) -> SearchPage {
            path "_search";
            query { pretty; }
            body json(pit_body(query, pit_id, keep_alive, size, cursor));
            paginate pit_after(cursor);
            idempotent;
        }
        DELETE close_pit(id: String, ..output) -> ClosedPit {
            path "_pit";
            body json(j!({ "id": id }));
            idempotent false;
        }
        GET cat_indices(format?: CatFormat, ..output) -> CatReply {
            path "_cat/indices";
            query { format; }
            read Text;
            status { 2xx { body } => cat_reply(body, format)? }
        }
    }
}

concord::api! {
